export const B1_RVR: Record<string, string> = {
  "wea-pro3-9": "Honra \u{e1} Jehov\u{e1} de tu sustancia, y de las primicias de todos tus frutos;",
  "wea-mal3-10": "Traed todos los diezmos al alfol\u{ed}, y haya alimento en mi casa; y probadme ahora en esto, dice Jehov\u{e1} de los ej\u{e9}rcitos, si no os abrir\u{e9} las ventanas de los cielos, y vaciar\u{e9} sobre vosotros bendici\u{f3}n hasta que sobreabunde.",
  "wea-2co9-7": "Cada uno d\u{e9} como propuso en su coraz\u{f3}n: no con tristeza, \u{f3} por necesidad; porque Dios ama el dador alegre.",
  "wea-1ti6-10": "Porque el amor del dinero es la ra\u{ed}z de todos los males: el cual codiciando algunos, se descaminaron de la fe, y fueron traspasados de muchos dolores.",
  "wea-1ti6-17": "A los ricos de este siglo manda que no sean altivos, ni pongan la esperanza en la incertidumbre de las riquezas, sino en el Dios vivo, que nos da todas las cosas en abundancia de que gocemos:",
  "wea-heb13-5": "Sean las costumbres vuestras sin avaricia; contentos de lo presente; porque \u{e9}l dijo: No te desamparar\u{e9}, ni te dejar\u{e9}.",
  "wea-mat6-19": "No os hag\u{e1}is tesoros en la tierra, donde la polilla y el or\u{ed}n corrompe, y donde ladrones minan y hurtan;",
  "wea-mat6-21": "Porque donde estuviere vuestro tesoro, all\u{ed} estar\u{e1} vuestro coraz\u{f3}n.",
  "wea-luk6-38": "Dad, y se os dar\u{e1}; medida buena, apretada, remecida, y rebosando dar\u{e1}n en vuestro seno: porque con la misma medida que midiereis, os ser\u{e1} vuelto \u{e1} medir.",
  "wea-pro11-25": "El alma liberal ser\u{e1} engordada: y el que saciare, \u{e9}l tambi\u{e9}n ser\u{e1} saciado.",
  "wea-deu8-18": "Antes acu\u{e9}rdate de Jehov\u{e1} tu Dios: porque \u{e9}l te da el poder para hacer las riquezas, \u{e1} fin de confirmar su pacto que jur\u{f3} \u{e1} tus padres, como en este d\u{ed}a.",
  "wea-act20-35": "En todo os he ense\u{f1}ado que, trabajando as\u{ed}, es necesario sobrellevar \u{e1} los enfermos, y tener presente las palabras del Se\u{f1}or Jes\u{fa}s, el cual dijo: M\u{e1}s bienaventurada cosa es dar que recibir.",
  "wea-ecc5-10": "El que ama el dinero, no se hartar\u{e1} de dinero; y el que ama el mucho tener, no sacar\u{e1} fruto. Tambi\u{e9}n esto es vanidad.",
  "wea-luk12-15": "Y d\u{ed}joles: Mirad, y guardaos de toda avaricia; porque la vida del hombre no consiste en la abundancia de los bienes que posee.",
  "hea-jer17-14": "S\u{e1}name, oh Jehov\u{e1}, y ser\u{e9} sano; s\u{e1}lvame, y ser\u{e9} salvo: porque t\u{fa} eres mi alabanza.",
  "hea-exo15-26": "Y dijo: Si oyeres atentamente la voz de Jehov\u{e1} tu Dios, \u{e9} hicieres lo recto delante de sus ojos, y dieres o\u{ed}do \u{e1} sus mandamientos, y guardares todos sus estatutos, ninguna enfermedad de las que envi\u{e9} \u{e1} los Egipcios te enviar\u{e9} \u{e1} ti; porque yo soy Jehov\u{e1} tu Sanador.",
  "hea-jas5-16": "Confesaos vuestras faltas unos \u{e1} otros, y rogad los unos por los otros, para que se\u{e1}is sanos; la oraci\u{f3}n del justo, obrando eficazmente, puede mucho.",
  "hea-isa53-5": "Mas \u{e9}l herido fu\u{e9} por nuestras rebeliones, molido por nuestros pecados: el castigo de nuestra paz sobre \u{e9}l; y por su llaga fuimos nosotros curados.",
  "hea-3jn1-2": "Amado, yo deseo que t\u{fa} seas prosperado en todas cosas, y que tengas salud, as\u{ed} como tu alma est\u{e1} en prosperidad.",
  "hea-pro17-22": "El coraz\u{f3}n alegre produce buena disposici\u{f3}n: mas el esp\u{ed}ritu triste seca los huesos.",
  "hea-psa103-3": "El es quien perdona todas tus iniquidades, el que sana todas tus dolencias;",
  "hea-jer30-17": "Mas yo har\u{e9} venir sanidad para ti, y te sanar\u{e9} de tus heridas, dice Jehov\u{e1}; porque Arrojada te llamaron, diciendo: Esta es Si\u{f3}n, \u{e1} la que nadie busca.",
  "hea-pro4-22": "Porque son vida \u{e1} los que las hallan, y medicina \u{e1} toda su carne.",
  "hea-isa58-8": "Entonces nacer\u{e1} tu luz como el alba, y tu salud se dejar\u{e1} ver presto; \u{e9} ir\u{e1} tu justicia delante de ti, y la gloria de Jehov\u{e1} ser\u{e1} tu retaguardia.",
  "hea-2co12-9": "Y me ha dicho: B\u{e1}state mi gracia; porque mi potencia en la flaqueza se perfecciona. Por tanto, de buena gana me gloriar\u{e9} m\u{e1}s bien en mis flaquezas, porque habite en m\u{ed} la potencia de Cristo.",
  "hea-mar5-34": "Y \u{e9}l le dijo: Hija, tu fe te ha hecho salva: ve en paz, y queda sana de tu azote.",
  "hea-psa41-3": "Jehov\u{e1} lo sustentar\u{e1} sobre el lecho del dolor: mullir\u{e1}s toda su cama en su enfermedad.",
  "hea-psa6-2": "Ten misericordia de m\u{ed}, oh Jehov\u{e1}, porque yo estoy debilitado: s\u{e1}name, oh Jehov\u{e1}, porque mis huesos est\u{e1}n conmovidos.",
  "fr-pro17-17": "En todo tiempo ama el amigo; y el hermano para la angustia es nacido.",
  "fr-pro18-24": "El hombre que tiene amigos, ha de mostrarse amigo: y amigo hay m\u{e1}s conjunto que el hermano.",
  "fr-ecc4-9": "Mejores son dos que uno; porque tienen mejor paga de su trabajo.",
  "fr-ecc4-10": "Porque si cayeren, el uno levantar\u{e1} \u{e1} su compa\u{f1}ero: mas \u{a1}ay del solo! que cuando cayere, no habr\u{e1} segundo que lo levante.",
  "fr-jhn15-13": "Nadie tiene mayor amor que este, que ponga alguno su vida por sus amigos.",
  "fr-rom12-10": "Am\u{e1}ndoos los unos \u{e1} los otros con caridad fraternal; previni\u{e9}ndoos con honra los unos \u{e1} los otros;",
  "fr-pro13-20": "El que anda con los sabios, sabio ser\u{e1}; mas el que se allega \u{e1} los necios, ser\u{e1} quebrantado.",
  "fr-1co15-33": "No err\u{e9}is: las malas conversaciones corrompen las buenas costumbres.",
  "fr-pro27-6": "Fieles son las heridas del que ama; pero importunos los besos del que aborrece.",
  "fr-heb10-24": "Y consider\u{e9}monos los unos \u{e1} los otros para provocarnos al amor y \u{e1} las buenas obras;",
  "fr-gal6-2": "Sobrellevad los unos las cargas de los otros; y cumplid as\u{ed} la ley de Cristo.",
  "fr-rom12-15": "Gozaos con los que se gozan: llorad con los que lloran.",
  "fr-1th5-11": "Por lo cual, consolaos los unos \u{e1} los otros, y edificaos los unos \u{e1} los otros, as\u{ed} como lo hac\u{e9}is.",
  "fr-jhn13-34": "Un mandamiento nuevo os doy: Que os am\u{e9}is unos \u{e1} otros: como os he amado, que tambi\u{e9}n os am\u{e9}is los unos \u{e1} los otros.",
  "fam-gen2-24": "Por tanto, dejar\u{e1} el hombre \u{e1} su padre y \u{e1} su madre, y allegarse ha \u{e1} su mujer, y ser\u{e1}n una sola carne.",
  "fam-eph5-25": "Maridos, amad \u{e1} vuestras mujeres, as\u{ed} como Cristo am\u{f3} \u{e1} la iglesia, y se entreg\u{f3} \u{e1} s\u{ed} mismo por ella,",
  "fam-eph5-33": "Cada uno empero de vosotros de por s\u{ed}, ame tambi\u{e9}n \u{e1} su mujer como \u{e1} s\u{ed} mismo; y la mujer reverencie \u{e1} su marido.",
  "fam-eph5-21": "Sujetados los unos \u{e1} los otros en el temor de Dios.",
  "fam-pro18-22": "El que hall\u{f3} esposa hall\u{f3} el bien, y alcanz\u{f3} la benevolencia de Jehov\u{e1}.",
  "fam-ecc4-12": "Y si alguno prevaleciere contra el uno, dos estar\u{e1}n contra \u{e9}l; y cord\u{f3}n de tres dobleces no presto se rompe.",
  "fam-pro22-6": "Instruye al ni\u{f1}o en su carrera: aun cuando fuere viejo no se apartar\u{e1} de ella.",
  "fam-eph6-1": "HIJOS, obedeced en el Se\u{f1}or \u{e1} vuestros padres; porque esto es justo.",
  "fam-eph6-4": "Y vosotros, padres, no provoqu\u{e9}is \u{e1} ira \u{e1} vuestros hijos; sino criadlos en disciplina y amonestaci\u{f3}n del Se\u{f1}or.",
  "fam-jos24-15": "Y si mal os parece servir \u{e1} Jehov\u{e1}, escogeos hoy \u{e1} qui\u{e9}n sirv\u{e1}is; si \u{e1} los dioses \u{e1} quienes sirvieron vuestros padres, cuando estuvieron de esotra parte del r\u{ed}o, \u{f3} \u{e1} los dioses de los Amorrheos en cuya tierra habit\u{e1}is: que yo y mi casa serviremos \u{e1} Jehov\u{e1}.",
  "fam-psa127-1": "SI Jehov\u{e1} no edificare la casa, en vano trabajan los que la edifican: si Jehov\u{e1} no guardare la ciudad, en vano vela la guarda.",
  "fam-psa127-3": "He aqu\u{ed}, heredad de Jehov\u{e1} son los hijos: cosa de estima el fruto del vientre.",
  "fam-deu6-7": "Y las repetir\u{e1}s \u{e1} tus hijos, y hablar\u{e1}s de ellas estando en tu casa, y andando por el camino, y al acostarte, y cuando te levantes:",
  "fam-mar10-9": "Pues lo que Dios junt\u{f3}, no lo aparte el hombre.",
  "lh-1pe1-3": "Bendito el Dios y Padre de nuestro Se\u{f1}or Jesucristo, que seg\u{fa}n su grande misericordia nos ha regenerado en esperanza viva, por la resurrecci\u{f3}n de Jesucristo de los muertos,",
  "lh-rom15-13": "Y el Dios de esperanza os llene de todo gozo y paz creyendo, para que abund\u{e9}is en esperanza por la virtud del Esp\u{ed}ritu Santo.",
  "lh-jer29-11": "Porque yo s\u{e9} los pensamientos que tengo acerca de vosotros, dice Jehov\u{e1}, pensamientos de paz, y no de mal, para daros el fin que esper\u{e1}is.",
  "lh-heb6-19": "La cual tenemos como segura y firme ancla del alma, y que entra hasta dentro del velo;",
  "lh-rom5-5": "Y la esperanza no averg\u{fc}enza; porque el amor de Dios est\u{e1} derramado en nuestros corazones por el Esp\u{ed}ritu Santo que nos es dado.",
  "lh-psa39-7": "Y ahora, Se\u{f1}or, \u{bf}qu\u{e9} esperar\u{e9}? Mi esperanza en ti est\u{e1}.",
  "lh-lam3-24": "Mi parte es Jehov\u{e1}, dijo mi alma; por tanto en \u{e9}l esperar\u{e9}.",
  "lh-rom12-12": "Gozosos en la esperanza; sufridos en la tribulaci\u{f3}n; constantes en la oraci\u{f3}n;",
  "lh-heb10-23": "Mantengamos firme la profesi\u{f3}n de nuestra fe sin fluctuar; que fiel es el que prometi\u{f3}:",
  "lh-psa62-5": "Alma m\u{ed}a, en Dios solamente reposa; porque de \u{e9}l es mi esperanza.",
  "lh-pro23-18": "Porque ciertamente hay fin, y tu esperanza no ser\u{e1} cortada.",
  "lh-psa71-14": "Mas yo siempre esperar\u{e9}, y a\u{f1}adir\u{e9} sobre toda tu alabanza.",
  "lh-tit2-13": "Esperando aquella esperanza bienaventurada, y la manifestaci\u{f3}n gloriosa del gran Dios y Salvador nuestro Jesucristo,",
  "lh-col1-27": "A los cuales quiso Dios hacer notorias las riquezas de la gloria de este misterio entre los Gentiles; que es Cristo en vosotros la esperanza de gloria:",
};
